**Validate the exact 98-row paired set.**

This run intentionally compares 98 samples against a 100-row baseline. The verifier must allow baseline-only rows, but it must require every current row to match one replay sample and one unique baseline row. It must also validate `tally.paired.verses`; the current check validates only improved and regressed counts.

<details>
<summary>Suggested fix</summary>

```diff
-const baseRows = new Map(base("tally.json").rows.map((r: { id: string; accepted: boolean }) => [r.id, r.accepted]));
+const baselineTally = base("tally.json");
+const sampleIds = samples.map((s: { id: string }) => s.id);
+const baselineIds = baselineTally.rows.map((r: { id: string }) => r.id);
+const tallyIds = tally.rows.map((r: { id: string }) => r.id);
+for (const ids of [sampleIds, baselineIds, tallyIds]) assert.equal(new Set(ids).size, ids.length);
+assert.equal(tallyIds.length, sampleIds.length);
+assert.deepEqual([...tallyIds].sort(), [...sampleIds].sort());
+const baseRows = new Map(baselineTally.rows.map((r: { id: string; accepted: boolean }) => [r.id, r.accepted]));
+for (const id of sampleIds) assert.ok(baseRows.has(id), id);
+assert.equal(tally.paired.verses, sampleIds.length);
```

